insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('KM', 'KM-P-10', 'Achat local, taux 10 %, non déductible', '{}'::jsonb, 'La taxe facturée par un fournisseur local est un coût : aucune déduction de la TC payée sur les achats locaux n''a été trouvée dans le texte, hors le cas particulier du crédit-bail (art. 141-16), non modélisé (voir README)', 'percent', 10, 'purchase', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 150 — la régularisation de la taxe payée en douane à l''importation ne porte que sur celle-ci et ne peut aboutir à un remboursement ; aucun article n''organise de déduction générale de la taxe supportée sur un achat local, à la différence d''une TVA. La taxe supportée est donc une part du coût de ce qui a été acheté.', null, null, 200, 'sales_tax', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-P-IMP-10', 'Importation, taux 10 %, TC payée en douane, acompte imputable', '{}'::jsonb, 'La taxe payée en douane à l''importation est un acompte imputable sur la taxe due lors de la revente, jamais remboursable', 'percent', 10, 'purchase', 'import', date '2020-01-01', null, 'Code général des impôts, art. 150 — la taxe payée en douane à l''importation est imputable sur la taxe due au titre des ventes ultérieures ; « en aucun cas la régularisation ne peut aboutir à un remboursement de la taxe perçue à l''importation ». Le formulaire officiel porte cette imputation à la ligne « Acomptes payés » (L3), reportée ici sur la case ACPT.', null, null, 210, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'formulaire-tc-ts', null, null, null, null),
  ('KM', 'KM-P-NR-10', 'Services d''un prestataire non domicilié, taux 10 %, autoliquidation', '{}'::jsonb, 'Le preneur autoliquide la taxe qu''un prestataire non domicilié aux Comores n''a pas facturée ; comme pour un achat local, rien ne montre qu''elle soit déductible', 'percent', 10, 'purchase', 'foreign_services_received', date '2020-01-01', null, 'Code général des impôts, art. 149 (dans la rédaction de la loi de finances rectificative 2020 et de la loi de finances rectificative 2022) — autoliquidation par le preneur de la taxe due sur les services rendus par un prestataire non domicilié aux Comores. Aucun article ne prévoit sa déduction, ni la case du formulaire où elle serait reportée : le formulaire consulté ne porte qu''une ligne « Acomptes payés » réservée à l''article 150 (importations). La taxe autoliquidée est donc portée en coût et en dette envers l''État, sans case déclarative — voir README.', null, null, 220, 'sales_tax', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-00', 'Produits de première nécessité, taux 0 %', '{}'::jsonb, 'Viandes, volailles, poissons frais ou congelés, riz ordinaire, farine, sucre, médicaments, lait infantile — taxés à 0 %, ce qui n''est pas une exonération de l''article 141 : le formulaire officiel ne porte pourtant pas de colonne à 0 % et range ces opérations dans la même colonne « Exonérés » que les opérations de l''article 141 (voir KM-S-EXO). Le pack suit le formulaire sur ce point et l''écrit dans le README plutôt que d''inventer une case.', 'percent', 0, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux de 0 % pour les produits de première nécessité, renvoyant à une liste fixée par arrêté ; arrêté n° 17-065/MFB/CAB du 19 septembre 2017 — liste : viandes, volailles, poissons frais ou congelés, riz ordinaire, farine, sucre, médicaments, lait infantile, applicable à l''importation comme à l''intérieur.', null, null, 30, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-03-TRANSPORT', 'Titres de transport inter-îles, taux 3 %', '{}'::jsonb, null, 'percent', 3, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux de 3 % pour les titres de transport inter-îles, distincts de la fourniture d''eau et d''électricité au même taux (voir KM-S-03-UTIL) et des titres de transport international, taxés à 5 % (voir KM-S-05-TRANSPORT-INTL).', null, null, 50, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-03-UTIL', 'Fourniture d''eau et d''électricité, taux 3 %', '{}'::jsonb, null, 'percent', 3, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux de 3 % pour la fourniture d''eau et d''électricité.', null, null, 40, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-05-SRV', 'Restauration, activités bancaires, téléphone fixe, taux 5 %', '{}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux de 5 % pour la restauration, les activités bancaires et le téléphone fixe. Ces trois activités et les titres de transport international (voir KM-S-05-TRANSPORT-INTL) sont au même taux de 5 % mais de nature différente : deux codes, pour que chacun garde son propre article.', null, null, 60, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-05-TRANSPORT-INTL', 'Titres de transport international, taux 5 %', '{}'::jsonb, null, 'percent', 5, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux de 5 % pour les titres de transport international, à distinguer des titres de transport inter-îles, taxés à 3 % (voir KM-S-03-TRANSPORT).', null, null, 70, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-075-MOBILE', 'Recharges mobiles, voix et données, taux 7,5 %', '{}'::jsonb, null, 'percent', 7.5, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux de 7,5 % pour les recharges mobiles, voix et données. Une taxe annexe de 50 KMF par minute sur les terminaisons d''appels entrants existe au même article (in fine) et n''est pas modélisée ici : elle ne se rattache à aucune ligne de facture de vente, voir README.', null, null, 80, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-10', 'Ventes de biens, taux normal 10 %', '{}'::jsonb, 'Vente ou production de biens au taux normal de la taxe sur la consommation, TC au compte 4431', 'percent', 10, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux normal de 10 %, dans la rédaction résultant des lois de finances 2018, 2019, 2020 et de la loi de finances rectificative 2020, la dernière modification isolée dans le texte consulté ; la date exacte d''entrée en vigueur du taux de 10 % n''a pas été trouvée, seule la liste des lois modificatives l''est. Art. 139 — la taxe s''applique aux activités d''achats-reventes et de productions de biens.', null, null, 10, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-10-SRV', 'Prestations de services, taux normal 10 %', '{}'::jsonb, 'Prestation de services au taux normal de la taxe sur la consommation, TC au compte 4432', 'percent', 10, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux normal de 10 %, dans la rédaction résultant des lois de finances 2018, 2019, 2020 et de la loi de finances rectificative 2020 ; art. 139 — la taxe s''applique également aux services.', null, null, 20, 'sales_tax', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-25-CASINO', 'Activités des casinos, taux 25 %', '{}'::jsonb, null, 'percent', 25, 'sale', 'domestic', date '2020-01-01', null, 'Code général des impôts, art. 152 — taux de 25 % pour les activités des casinos.', null, null, 90, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-EXO', 'Opération exonérée (art. 141)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2020-01-01', null, 'Code général des impôts, art. 141 (dans la rédaction de la loi de finances rectificative 2022 et de la loi de finances 2023) — quinze catégories d''opérations exonérées : notamment les organismes sans but lucratif, la presse hors publicité, les ventes des agriculteurs, éleveurs, pêcheurs et maraîchers, les marchés financés par des aides extérieures, les écolages privés, les professions médicales, l''immobilier soumis à l''enregistrement, les assurances et le crédit-bail. Le seuil de chiffre d''affaires (art. 141-1°) est une qualité du redevable et non une opération ; il n''a pas de code ici.', null, null, 100, 'sales_tax', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('KM', 'KM-S-EXPORT', 'Exportation exonérée', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2020-01-01', null, 'Code général des impôts, art. 141, 2° — exonération des exportations et des services directement liés ; art. 148 — la facture porte la référence à la disposition d''exonération. Le formulaire de déclaration ne porte qu''une colonne « Exonérés », sans case distincte pour l''export : ce code partage la case EXO avec KM-S-EXO et KM-S-00, et se distingue par le traitement `export`, qui gouverne la mention de facture et non la case déclarative.', null, null, 110, 'sales_tax', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

