insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('KM', 'KM-TC', 'Déclaration mensuelle et unifiée de la taxe sur la consommation', array['month']::declaration_period[], 'month'::declaration_period, date '2020-01-01', null, 'Code général des impôts, art. 149 — la déclaration de la taxe sur la consommation est mensuelle, déposée avant le 15 de chaque mois pour les opérations du mois précédent, en double exemplaire, au centre des impôts (DGE ou DPME) dont dépend le redevable. Le formulaire officiel de l''AGID, « Déclaration mensuelle et unifiée de la Taxe sur la Consommation (TC), Taxe sur les Salaires (TS) », porte les colonnes Exonérés / Taxables à 3 %, 5 %, 7,5 %, 10 %, 15 % et 25 % et les lignes L1 à L6 de la TC (la partie « Taxe sur les Salaires » de l''imprimé, L7-L8, est un impôt distinct sur les rémunérations et n''appartient pas à ce pack). La colonne à 15 % du formulaire ne correspond à aucun taux de l''article 152 du CGI 2023 lu pour ce pack et n''est pas reprise ici, faute de base légale trouvée — voir README. La télédéclaration devient obligatoire à compter du 1er janvier 2026 pour les moyennes et grandes entreprises (loi de finances 2024, art. L.4 du livre de procédures fiscales modifié), mais aucune plateforme opérationnelle n''a été trouvée à la date de ce pack.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Code général des impôts, art. 149 — la déclaration est déposée avant le 15 de chaque mois, pour les opérations du mois précédent.', 'cgi', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
