values
  ('KM', 'KM-TC', 'EXO', 'base', 'Opérations exonérées (colonne « Exonérés » du formulaire)', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 141 — opérations exonérées ; art. 152 — produits de première nécessité taxés à 0 %. Le formulaire officiel ne porte qu''une colonne « Exonérés », sans case distincte pour un taux à 0 % ni pour l''export : les trois s''y reportent (KM-S-EXO, KM-S-00, KM-S-EXPORT).', 'formulaire-tc-ts'),
  ('KM', 'KM-TC', 'B03', 'base', 'Opérations taxables à 3 %', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 152 — taux de 3 % ; formulaire officiel, colonne « Taxables à 3 % »', 'formulaire-tc-ts'),
  ('KM', 'KM-TC', 'B05', 'base', 'Opérations taxables à 5 %', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 152 — taux de 5 % ; formulaire officiel, colonne « Taxables à 5 % »', 'formulaire-tc-ts'),
