  ('KM', 'KM-TC', 'TAXT', 'total', 'L2 — Montant de la taxe', '{}'::jsonb, 130, null, array['T03', 'T05', 'T075', 'T10', 'T25']::text[], '{}'::text[], null, null, false, false, null, 'Formulaire officiel, ligne L2 « Montant de la taxe »', 'formulaire-tc-ts'),
  ('KM', 'KM-TC', 'ACPT', 'tax', 'L3 — Acomptes payés (TC payée en douane à l''importation)', '{}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 150 — la taxe payée en douane à l''importation est un acompte imputable sur la taxe due au titre des ventes ultérieures ; formulaire officiel, ligne L3 « Acomptes payés »', 'formulaire-tc-ts'),
  ('KM', 'KM-TC', 'NET', 'total', 'L5 — Taxe due au titre du mois', '{}'::jsonb, 150, null, array['TAXT']::text[], array['ACPT']::text[], null, null, true, false, null, 'Formulaire officiel, ligne L5 « Taxe due au titre du mois (L2-L3-L4) ». Ce pack ne reporte pas de case pour L4, le solde créditeur de la déclaration précédente : elle n''est pas un fait de la période mais le report du calcul du mois antérieur, que la case CRED porte déjà d''un mois sur l''autre.', 'formulaire-tc-ts'),
  ('KM', 'KM-TC', 'CRED', 'total', 'L6 — Solde créditeur à reporter', '{}'::jsonb, 160, null, array['ACPT']::text[], array['TAXT']::text[], null, null, true, false, null, 'Code général des impôts, art. 150 — « en aucun cas la régularisation ne peut aboutir à un remboursement de la taxe perçue à l''importation » : l''excédent d''acomptes ne se reporte que sur les mois suivants, jamais en remboursement. Formulaire officiel, ligne L6 « Solde créditeur à reporter ».', 'cgi')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('KM-SYSCOHADA-BS', 'KM', 'default', 'Bilan — Système normal', 'balance_sheet', 'SYSCOHADA', date '2018-01-01', null, 'Acte uniforme relatif au droit comptable et à l''information financière (AUDCIF) du 26 janvier 2017, art. 25, 26 et 29 ; Système comptable OHADA, Titre IX, chapitre 3 (modèle de bilan) et chapitre 7 (tableau de correspondance postes/comptes). En vigueur pour les comptes personnels des entités au 1er janvier 2018 (AUDCIF, art. 113).', 'syscohada'),
  ('KM-SYSCOHADA-IS', 'KM', 'default', 'Compte de résultat — Système normal', 'income_statement', 'SYSCOHADA', date '2018-01-01', null, 'Acte uniforme relatif au droit comptable et à l''information financière (AUDCIF) du 26 janvier 2017, art. 25, 26 et 29 ; Système comptable OHADA, Titre IX, chapitre 4 (modèle de compte de résultat) et chapitre 7 (tableau de correspondance postes/comptes). Les charges y sont lues en positif et retranchées par les soldes intermédiaires, là où le modèle les imprime affectées du signe « - ».', 'syscohada')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

