  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Code général des impôts, art. 148 — tout redevable de la taxe sur la consommation doit délivrer une facture ou un document en tenant lieu portant, entre autres mentions, « la date et le numéro de série de la facture ». Le texte impose un numéro de série mais ne prescrit ni une forme ni l''interdiction d''un trou dans la séquence, à la différence du Sénégal (art. 447-I-5, « séquence chronologique et continue ») : `sequential` dit ce que l''article impose, pas plus.',
  numbering_source_key          = 'cgi',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Code général des impôts, art. 148 — tout redevable de la taxe sur la consommation « doit délivrer une facture ou un document en tenant lieu » qui porte le taux et le montant de la taxe appliquée, et art. 139 — la taxe s''applique aux activités d''achats-reventes, de productions et de services. Aucun article fixant expressément le fait générateur (livraison, encaissement ou émission de la facture) n''a été trouvé dans le texte consulté : `invoice_if_issued` retient la facture, seul document que l''article 148 rend obligatoire à chaque opération, faute d''un texte trouvé sur le fait générateur lui-même. À vérifier auprès d''un fiscaliste comorien.',
  tax_point_source_key          = 'cgi',
