 where country = 'KM';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('KM', 'exempt', 'exempt', 'Opération exonérée de la taxe sur la consommation — article 141 du Code général des impôts.', '{}'::jsonb, 10, date '1970-01-01', null, 'Code général des impôts, art. 148 — la facture porte les mentions que l''article prescrit, dont le taux de taxe appliqué ; art. 141 — liste des opérations exonérées'),
  ('KM', 'export', 'export', 'Exportation exonérée de la taxe sur la consommation — article 141, 2° du Code général des impôts.', '{}'::jsonb, 20, date '1970-01-01', null, 'Code général des impôts, art. 148 et art. 141, 2° — exportations et services directement liés'),
  ('KM', 'no_tax_mentioned', 'always', 'Toute facture ne mentionnant pas la taxe sur la consommation est considérée comme taxe incluse — article 148 du Code général des impôts.', '{}'::jsonb, 90, date '1970-01-01', null, 'Code général des impôts, art. 148, dernier alinéa — « Toute facture ne mentionnant pas la taxe sera considérée comme taxe incluse. » La condition porte sur ce que la facture omet et non sur la nature de l''opération : `always` est la seule valeur du vocabulaire fermé qui l''atteint, faute d''une valeur voisine de « la taxe manque sur ce document ». Le rendu conditionnel réel — n''imprimer la phrase que si la taxe est absente — n''est pas exprimable ici et reste à faire ailleurs.')
